// Undeformed local centimetres keep the finish attached during reload.
// Fine detail affects roughness only; UV0 structure remains unchanged.
float3 weights = pow(abs(normalize(N)), float3(6, 6, 6));
weights /= max(dot(weights, float3(1, 1, 1)), 0.0001);
float3 q = P / 5.0;
float grain = dot(weights, float3(
    Texture2DSample(FinishTex, FinishTexSampler, q.yz).r,
    Texture2DSample(FinishTex, FinishTexSampler, q.xz).r,
    Texture2DSample(FinishTex, FinishTexSampler, q.xy).r));
return clamp(Base + (grain - 0.5) * Amplitude, 0.04, 0.96);

